using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5%: 249.95 -> 249 discount
    [InlineData(LoyaltyTier.Gold, 4_999, 4_650)]     // 7%: 349.93 -> 349
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_549)]  // 9%: 449.91 -> 449
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // 50.00 enters 1-point band: 6%
    [InlineData(LoyaltyTier.Gold, 5_000, 4_600)]     // 8%
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)] // 10%
    [InlineData(LoyaltyTier.Green, 19_999, 18_799)]  // 6%: 1199.94 -> 1199
    [InlineData(LoyaltyTier.Platinum, 19_999, 18_000)] // capped 10%: 1999.9 -> 1999
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 200.00 enters 3-point band: 8%
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12% capped to 10%
    [InlineData(LoyaltyTier.Green, 99, 95)]          // 4.95 -> 4 discount, rounded down
    [InlineData(LoyaltyTier.Green, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier tier, int subtotalCents, int expectedPayableCents)
    {
        Assert.Equal(expectedPayableCents, new CalculatePayableTotal().For(subtotalCents, tier));
    }
}
E
